# owner: platform
from typing import List
from rosterkit.models import Student
from rosterkit.errors import ProjectError

def _check(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students given")
    for student in students:
        if not student.email:
            raise ProjectError(
                f"no email for {student.display_name}"
            )

def _cells(student: Student) -> tuple:
    return (
        student.display_name,
        student.section,
        student.email,
    )

def _line(cells: tuple, widths: List[int]) -> str:
    padded = [c.ljust(w) for c, w in zip(cells, widths)]
    return "  ".join(padded).rstrip()

# ---
def contact_rows(students: List[Student]) -> List[str]:
    _check(students)
    ordered = sorted(students, key=lambda s: _cells(s))
    cells = [_cells(s) for s in ordered]
    widths = [max(map(len, col)) for col in zip(*cells)]
    return [_line(c, widths) for c in cells]

