# owner: platform
import unittest
from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows

def _kid(last, first, section, email):
    return Student("1", last, first, section, email)

class ContactRowTests(unittest.TestCase):
    def test_rows_are_sorted_and_aligned(self):
        rows = contact_rows([
            _kid("Zed", "Al", "B", "al@x.org"),
            _kid("Ames", "Bo", "A", "bo@x.org"),
        ])
        self.assertEqual(rows, [
            "Ames, Bo  A  bo@x.org",
            "Zed, Al   B  al@x.org",
        ])

    def test_missing_email_names_student(self):
        kids = [_kid("Ames", "Bo", "A", None)]
        with self.assertRaises(ProjectError) as ctx:
            contact_rows(kids)
        self.assertIn("Ames, Bo", str(ctx.exception))

    def test_blank_email_is_missing(self):
        kids = [_kid("Ames", "Bo", "A", "")]
        with self.assertRaises(ProjectError):
            contact_rows(kids)

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])

if __name__ == "__main__":
    unittest.main()
